"""Lexer for MiniDB's SQL subset."""

from __future__ import annotations

from minidb.types import KEYWORDS, OPERATORS, SQLSyntaxError, Token, TokenType

__all__ = [
    "tokenize",
    "is_identifier_start",
    "is_identifier_char",
    "read_string_literal",
]


def is_identifier_start(ch: str) -> bool:
    """Return True if ``ch`` is an ASCII letter or underscore."""
    return ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def is_identifier_char(ch: str) -> bool:
    """Return True if ``ch`` is an ASCII letter, digit, or underscore."""
    return is_identifier_start(ch) or ("0" <= ch <= "9")


def read_string_literal(sql: str, start: int) -> tuple[str, int]:
    """Read a single-quoted string literal beginning at ``sql[start]``."""
    i = start + 1
    out = []
    while i < len(sql):
        if sql[i] == "'":
            if sql[i + 1:i + 2] == "'":
                out.append("'")
                i += 2
                continue
            return "".join(out), i + 1
        out.append(sql[i])
        i += 1
    raise SQLSyntaxError("unterminated string literal")


def tokenize(sql: str) -> list[Token]:
    """Convert ``sql`` into tokens, always ending with one EOF token."""
    tokens: list[Token] = []
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch.isspace():
            i += 1
        elif is_identifier_start(ch):
            j = i
            while j < n and is_identifier_char(sql[j]):
                j += 1
            word = sql[i:j]
            if word.upper() in KEYWORDS:
                tokens.append(Token(TokenType.KEYWORD, word.upper(), i))
            else:
                tokens.append(Token(TokenType.IDENTIFIER, word, i))
            i = j
        elif "0" <= ch <= "9":
            j = i
            while j < n and "0" <= sql[j] <= "9":
                j += 1
            tokens.append(Token(TokenType.INTEGER, sql[i:j], i))
            i = j
        elif ch == "'":
            value, end = read_string_literal(sql, i)
            tokens.append(Token(TokenType.STRING, value, i))
            i = end
        else:
            for op in OPERATORS:
                if sql.startswith(op, i):
                    tokens.append(Token(TokenType.OPERATOR, op, i))
                    i += len(op)
                    break
            else:
                raise SQLSyntaxError(f"unexpected character {ch!r} at {i}")
    tokens.append(Token(TokenType.EOF, "", n))
    return tokens

